namespace sv_5ab7857cef9841e5beeda04a8c6b5943.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnWarehouseChanged;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A - Main Distribution"),
        ("WH-002", "Warehouse B - East Regional"),
        ("WH-003", "Warehouse C - West Coast"),
        ("WH-004", "Warehouse D - Returns Processing"),
    ];
}

namespace sv_5ab7857cef9841e5beeda04a8c6b5943.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();
    private int _lastKnownCount;

    public int LastKnownCount => _lastKnownCount;

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components should re-render.
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the count of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component to refresh and broadcast new data.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        var count = await GetLowStockCountAsync(warehouseId);
        _lastKnownCount = count;
        OnAlertCountChanged?.Invoke();
    }
}

