@page "/dashboard"
@using sv_5ab7857cef9841e5beeda04a8c6b5943.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Current Site: @GetWarehouseName(WarehouseState.CurrentWarehouseId)
        </h5>
        <p class="text-muted">Warehouse ID: @WarehouseState.CurrentWarehouseId</p>
    </div>
</div>

<div class="row">
    <div class="col-md-4">
        <div class="card @(AlertService.LastKnownCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h2 class="@(AlertService.LastKnownCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.LastKnownCount
                </h2>
                <p class="card-text">Low-Stock Alerts</p>
                <small class="text-muted">
                    Polling every 10s &bull; Last check: @_lastPollTime?.ToString("HH:mm:ss")
                </small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h2>@WarehouseState.CurrentWarehouseId</h2>
                <p class="card-text">Active Warehouse</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h2>@(_isPolling ? "Active" : "Stopped")</h2>
                <p class="card-text">Polling Status</p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _pollingCts;
    private DateTime? _lastPollTime;
    private bool _isPolling;

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertDataChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    private async void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse immediately
        StopPolling();
        await InvokeAsync(async () =>
        {
            await StartPollingAsync();
            StateHasChanged();
        });
    }

    private void OnAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task StartPollingAsync()
    {
        _pollingCts = new CancellationTokenSource();
        _isPolling = true;
        var token = _pollingCts.Token;

        // Initial fetch
        await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
        _lastPollTime = DateTime.Now;
        StateHasChanged();

        // Background polling loop
        _ = Task.Run(async () =>
        {
            while (!token.IsCancellationRequested)
            {
                try
                {
                    await Task.Delay(TimeSpan.FromSeconds(10), token);
                    await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
                    _lastPollTime = DateTime.Now;
                    await InvokeAsync(StateHasChanged);
                }
                catch (TaskCanceledException)
                {
                    break;
                }
            }
        }, token);
    }

    private void StopPolling()
    {
        _isPolling = false;
        _pollingCts?.Cancel();
        _pollingCts?.Dispose();
        _pollingCts = null;
    }

    private static string GetWarehouseName(string id) =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id).Name ?? id;

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnWarehouseChanged -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertDataChanged;
    }
}

